function renderRoster() {
 const r=state.room,s=r.season;
 return pageHead(`${s.team} · FIRST TEAM ROSTER`,'다섯 자리, 하나의 팀.','내 선수의 성장과 빈자리를 채운 NPC의 능력치를 함께 확인합니다. 상대 전력은 시즌 시작 전에 설정하며 시즌 중 고정됩니다. 팀 이름은 LCK 목록으로 고정됩니다.',`<button class="button" data-action="edit-portrait">프로필 사진 변경</button>`)+`<div class="roster-cards">${(r.roster||r.players.map(p=>p.character)).map(c=>{const human=r.players.find(p=>p.character.id===c.id);return `<section class="panel player-card"><div class="panel-header"><span class="tag ${human?'green':''}">${human?'PLAYER':'ROSTER NPC'}</span><span class="tiny-label">1군 · ${e(posName[c.position])}</span></div><div class="panel-body"><div class="player-head">${portrait(c,'medium')}<span class="position-badge">${e(c.position)}</span><div><h2>${e(c.nickname)}</h2><p>${e(human?.ownerName||'빈 포지션을 담당하는 팀원')} ${human?.userId===state.session.user.id?'· 나의 선수':''}</p></div></div>${Object.entries(statName).map(([key,label])=>`<div class="stat-line"><label>${label}</label><div class="bar"><span style="width:${Math.max(0,Math.min(100,c.stats?.[key]||0))}%"></span></div><strong>${Math.round(c.stats?.[key]||0)}</strong></div>`).join('')}<div class="state-pills"><span class="state-pill">컨디션 ${Math.round(c.condition||0)}</span><span class="state-pill">피로 ${Math.round(c.fatigue||0)}</span><span class="state-pill">스트레스 ${Math.round(c.stress||0)}</span></div><div class="divider" style="margin:15px 0"></div><p class="note">주력 ${e(c.mainChampion)} · ${e(c.style||'균형 운영')}<br>챔피언 풀: ${e((c.pool||[]).join(', '))}</p></div></section>`}).join('')}</div><div class="section-heading section-gap"><h2>상대 팀 스카우팅</h2><span class="tiny-label">가상 능력치 · 현실 선수·팀에 대한 평가가 아닙니다.</span></div><div class="npc-settings">${(Array.isArray(s.opponents)?s.opponents:Object.entries(s.opponents||{}).map(([name,v])=>({name,...v}))).map(t=>`<section class="panel opponent-view"><div class="row between"><h3>${e(t.name||t.team)}</h3><span class="tag blue">전력 ${e(t.power??'—')} · ${e(t.style||'균형 운영')}</span></div>${t.players?.length?`<div class="opponent-stats">${t.players.map(c=>`<div class="opponent-stat">${e(c.position)}<strong>${Math.round(Object.values(c.stats||{}).reduce((a,b)=>a+Number(b),0)/Math.max(1,Object.keys(c.stats||{}).length))}</strong></div>`).join('')}</div>`:'<p class="note">팀 전력과 플레이 성향을 경기 교전 판정에 반영합니다.</p>'}</section>`).join('')}</div><div class="notice section-gap">기본 능력치와 현재 상태는 구분됩니다. 피로·스트레스가 높으면 훈련으로 올린 능력도 경기에서 온전히 쓰지 못합니다. 분석은 운영, 합동 훈련은 소통, 휴식은 컨디션 관리에 도움이 됩니다.</div>`;
}
function locationSceneHTML(){const p=me();return renderLocationScene({location:p.location,players:state.room.players,roster:state.room.roster,me:p.userId,team:state.room.season.team,date:state.room.season.date});}
function refreshLocationScene() {
 const target=$('#location-scene');if(!target||state.view!=='dorm')return;
 const focused=document.activeElement?.matches('[data-scene-floor]');
 target.innerHTML=locationSceneHTML();if(focused)$('[data-scene-floor]',target)?.focus({preventScroll:true});
}
function moveInsideScene(x,y) {
 const player=me();if(!player||state.view!=='dorm'||state.busy||state.modal)return;
 const position={location:player.location,x:Math.max(8,Math.min(92,x)),y:Math.max(58,Math.min(90,y))};
 player.scenePosition=position;
 const sprite=$(`#location-scene [data-character-id="${CSS.escape(player.character.id)}"]`);
 sprite?.style.setProperty('--scene-x',`${position.x}%`);sprite?.style.setProperty('--scene-y',`${position.y}%`);
 clearTimeout(sceneMoveTimer);const version=++sceneMoveVersion,code=state.room.code;pendingSceneMove={code,position,version};
 sceneMoveTimer=setTimeout(async()=>{
  try{const data=await api(`/api/rooms/${encodeURIComponent(code)}/move`,{method:'POST',body:position});if(version===sceneMoveVersion&&state.room?.code===code){pendingSceneMove=null;setRoom(data.room,false);refreshLocationScene();}}
  catch(error){if(version===sceneMoveVersion){pendingSceneMove=null;toast(error.message,true);}}
 },250);
}
function renderDorm() {
 const p=me(),s=state.room.season,locations=state.meta.locations||['연습실','거실','주방','분석실','헬스장','매니저실','경기장','PC방','편의점','식당','카페','클리닉'];
 const normalizeLoc=x=>typeof x==='string'?x:x.name||x.id;
 const scenery={'연습실':'헤드셋을 내려놓자 키보드 소리가 남았다. 옆자리 모니터에는 방금 끝난 게임의 리플레이가 멈춰 있다.','거실':'소파에 누군가 벗어 둔 팀 재킷이 걸려 있다. TV에서는 다른 팀의 경기 영상이 나온다.','주방':'냉장고 문에 식단표가 붙어 있다. 매니저가 이름 옆에 체크 표시를 했다.','분석실':'분석관이 바텀 강가를 확대했다. 와드 하나가 화면 중앙에 남아 있다.','헬스장':'트레이너가 손목 상태부터 물었다. 벤치 옆에 물병이 놓였다.','매니저실':'문 옆에 이번 주 이동 일정이 붙어 있다. 매니저가 의자를 하나 당겨 줬다.','경기장':'백스테이지에 케이블 박스가 쌓여 있다. 무대 쪽에서 음향 확인 소리가 들렸다.','PC방':'옆자리에서 의자가 밀렸다. 메뉴판에는 새 야식이 추가돼 있다.','편의점':'도시락 진열대 앞에서 잠깐 멈췄다. 점원이 계산대 위 영수증을 정리한다.','식당':'팀원들이 구석 테이블을 맡아 뒀다. 물컵은 다섯 개다.','카페':'창가 자리에서 숙소로 가는 길이 보인다. 휴대폰에 팀 단톡방 알림이 떴다.','클리닉':'대기표의 숫자가 바뀌었다. 의사가 다음 경기 날짜를 확인했다.'};
 const rel=(s.relationships||[]).filter(x=>x.userId===p.userId);
 return pageHead('TEAM HOUSE & DAILY LIFE','경기장 밖에서도, 팀원.','장소를 옮기고 동료와 이야기하세요. 이동과 자유 대화는 턴을 쓰지 않으며, 능력치 변화는 정산 행동으로만 발생합니다.')+`<section class="panel location-scene-panel"><div id="location-scene">${locationSceneHTML()}</div><div class="panel-footer">바닥을 누르거나 장면에 포커스를 두고 방향키·WASD로 이동합니다. 선수 캐릭터를 누르면 프로필을 볼 수 있습니다. 이동은 턴과 능력치를 바꾸지 않습니다.</div></section><div class="dorm-layout section-gap"><section class="panel"><div class="panel-header"><h2>이동 지도</h2><span class="tag green">현재 ${e(p.location||'연습실')}</span></div><div class="panel-body"><div class="map-category">TEAM HOUSE / OUTSIDE</div><div class="dorm-map">${locations.map((raw,i)=>{const loc=normalizeLoc(raw);return `<button class="map-place ${p.location===loc?'current':''}" data-action="move" data-location="${e(loc)}"><span aria-hidden="true">${['⌘','▱','☕','▤','↟','▣','⚑','⌨','▥','♧','◌','✚'][i%12]}</span>${e(loc)}</button>`}).join('')}</div><div class="divider"></div><div class="eyebrow accent" style="margin-bottom:10px">${e(p.location||'연습실')} · ${e(p.character.nickname)}</div><p class="life-prose">${e(scenery[p.location]||'문을 열고 들어섰다. 팀원에게 현재 위치를 알렸다.')}</p><button class="button ghost" data-action="nav" data-view="chat">선수단 채팅에서 이어가기 →</button></div></section><div class="stack"><section class="panel"><div class="panel-header"><h2>고정 듀오 · 훈련 파트너</h2><span class="eyebrow">TRAINING PARTNER</span></div><div class="panel-body"><p class="note" style="margin-bottom:14px">고정 파트너가 없으면 듀오 행동 정산 시 임시 NPC가 배정됩니다. 임시 배정은 활동 후 해제되며 기록만 남습니다. 로스터 NPC와는 별개입니다.</p><form class="partner-select" data-form="duo"><label class="field" style="flex:1">나의 파트너<select name="target"><option value="">고정 듀오 없음</option>${state.room.players.filter(x=>x.userId!==p.userId).map(x=>`<option value="${e(x.userId)}" ${p.duoId===x.userId?'selected':''}>${e(x.character.nickname)} · ${e(posName[x.character.position])}</option>`).join('')}${(state.room.roster||[]).filter(c=>!state.room.players.some(x=>x.character.id===c.id)).map(c=>`<option value="NPC:${e(c.position)}" ${p.duoId===`NPC:${c.position}`?'selected':''}>${e(c.nickname)} · NPC ${e(posName[c.position])}</option>`).join('')}</select></label><button class="button" type="submit" style="align-self:end">등록</button></form></div></section><section class="panel"><div class="panel-header"><h2>관계와 함께한 기억</h2><span class="eyebrow">RELATIONSHIP LOG</span></div><div class="panel-body">${rel.length?rel.map(x=>`<div class="relationship"><div class="row between"><strong>${e(x.targetName||x.targetId)}</strong><span class="tag green">친밀도 ${e(x.affinity)}</span></div>${(x.memories||[]).slice(0,3).map(m=>`<small>${shortDate(m.date)} · ${e(m.text)}</small>`).join('')}</div>`).join(''):'<p class="note">듀오 연습이나 합동 활동을 정산하면 함께한 기록이 쌓입니다. 오너 채팅은 캐릭터 관계에 반영되지 않습니다.</p>'}</div></section></div></div>`;
}
